package com.jnapanam.sportszone.tournament.model;import com.jnapanam.sportszone.catalog.model.Sport;import com.jnapanam.sportszone.identity.model.User;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.*;
@Entity@Table(name="tournaments")public class Tournament{@Id private UUID id;@Column(nullable=false,unique=true,length=40)private String code;@Column(nullable=false,length=160)private String name;@Column(columnDefinition="TEXT")private String description;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="sport_id")private Sport sport;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="organizer_user_id")private User organizer;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private TournamentFormat format;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private TournamentStatus status;@Column(name="registration_opens",nullable=false)private LocalDate registrationOpens;@Column(name="registration_closes",nullable=false)private LocalDate registrationCloses;@Column(name="start_date",nullable=false)private LocalDate startDate;@Column(name="end_date",nullable=false)private LocalDate endDate;@Column(name="team_size",nullable=false)private int teamSize;@Column(name="max_teams",nullable=false)private int maxTeams;@Column(name="entry_fee",nullable=false,precision=12,scale=2)private BigDecimal entryFee;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected Tournament(){}public Tournament(String c,String n,String d,Sport s,User o,TournamentFormat f,LocalDate ro,LocalDate rc,LocalDate sd,LocalDate ed,int ts,int mt,BigDecimal fee){id=UUID.randomUUID();code=c.trim().toUpperCase(Locale.ROOT);name=n.trim();description=clean(d);sport=s;organizer=o;format=f;registrationOpens=ro;registrationCloses=rc;startDate=sd;endDate=ed;teamSize=ts;maxTeams=mt;entryFee=fee;status=TournamentStatus.DRAFT;createdAt=Instant.now();updatedAt=createdAt;}public void update(String n,String d,Sport s,User o,TournamentFormat f,LocalDate ro,LocalDate rc,LocalDate sd,LocalDate ed,int ts,int mt,BigDecimal fee){name=n.trim();description=clean(d);sport=s;organizer=o;format=f;registrationOpens=ro;registrationCloses=rc;startDate=sd;endDate=ed;teamSize=ts;maxTeams=mt;entryFee=fee;updatedAt=Instant.now();}public void status(TournamentStatus s){status=s;updatedAt=Instant.now();}public UUID getId(){return id;}public String getCode(){return code;}public String getName(){return name;}public String getDescription(){return description;}public Sport getSport(){return sport;}public User getOrganizer(){return organizer;}public TournamentFormat getFormat(){return format;}public TournamentStatus getStatus(){return status;}public LocalDate getRegistrationOpens(){return registrationOpens;}public LocalDate getRegistrationCloses(){return registrationCloses;}public LocalDate getStartDate(){return startDate;}public LocalDate getEndDate(){return endDate;}public int getTeamSize(){return teamSize;}public int getMaxTeams(){return maxTeams;}public BigDecimal getEntryFee(){return entryFee;}private static String clean(String v){return v==null||v.isBlank()?null:v.trim();}}
